#!/usr/bin/env python3
"""Fetch raw order listing pages and the customer records for shipped orders.

No calculation happens here. Output goes to /tmp/recon:
  pages.json      every listing page, in the order the server returned them
  customers.json  customer record per distinct customer_id of a shipped order
"""
import json
import sys
import time
import urllib.error
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"
OUT = "/tmp/recon"
TIMEOUT = 30
MAX_ATTEMPTS = 60

seen = Counter()
token = None
token_fetches = 0


def log(*parts):
    print(*parts, file=sys.stderr, flush=True)


def raw_request(path, method, auth):
    headers = {}
    if auth:
        headers["Authorization"] = "Bearer " + token
    data = b"" if method == "POST" else None
    req = urllib.request.Request(BASE + path, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as err:
        return err.code, err.headers, err.read()


def note(kind, status, headers, body):
    # Keep the first few examples of each kind of non-200 so the formats are visible.
    seen[(kind, status)] += 1
    if seen[(kind, status)] <= 3:
        log(f"[{kind} {status}] headers={dict(headers)} body={body[:400]!r}")


def wait_seconds(headers, body):
    value = headers.get("Retry-After")
    if value:
        try:
            return float(value)
        except ValueError:
            pass
    try:
        data = json.loads(body)
    except ValueError:
        data = {}
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds", "wait_seconds"):
            if key in data:
                return float(data[key])
    log(f"  429 without a readable wait time; sleeping 10s")
    return 10.0


def call(path, method="GET", auth=True, allow_404=False):
    global token
    delay = 1.0
    for _ in range(MAX_ATTEMPTS):
        if auth and token is None:
            token = fetch_token()
        try:
            status, headers, body = raw_request(path, method, auth)
        except OSError as err:
            note("network", "error", {}, str(err).encode())
            time.sleep(delay)
            delay = min(delay * 2, 30)
            continue
        if status == 200:
            try:
                return json.loads(body)
            except ValueError:
                note("bad-json", status, headers, body)
        elif status == 404 and allow_404:
            note("not-found", status, headers, body)
            return None
        elif status in (401, 403) and auth:
            # Token expired (or was rejected): fetch a new one and retry the same request.
            note("auth", status, headers, body)
            token = None
            continue
        elif status == 429:
            note("rate-limit", status, headers, body)
            time.sleep(wait_seconds(headers, body))
            continue
        elif status >= 500:
            note("server", status, headers, body)
        else:
            raise RuntimeError(f"{status} on {path}: {body[:300]!r}")
        time.sleep(delay)
        delay = min(delay * 2, 30)
    raise RuntimeError(f"gave up on {path} after {MAX_ATTEMPTS} attempts")


def fetch_token():
    global token_fetches
    token_fetches += 1
    return call("/token", method="POST", auth=False)["token"]


def fetch_pages():
    pages = []
    path = "/orders?page=1"
    while path:
        page = call(path)
        if "items" not in page or "next" not in page:
            raise RuntimeError(f"unexpected body on {path}: {str(page)[:300]!r}")
        if page["page"] != len(pages) + 1:
            raise RuntimeError(f"expected page {len(pages) + 1}, server returned {page['page']}")
        pages.append({"path": path, "page": page["page"], "total_pages": page["total_pages"],
                      "next": page["next"], "items": page["items"]})
        log(f"page {page['page']}/{page['total_pages']}: {len(page['items'])} items, next={page['next']}")
        nxt = page["next"]
        if nxt is not None and nxt.startswith(BASE):
            nxt = nxt[len(BASE):]
        path = nxt
    return pages


def main():
    pages = fetch_pages()
    with open(f"{OUT}/pages.json", "w") as f:
        json.dump(pages, f)

    shipped_customers = sorted({o["customer_id"] for p in pages for o in p["items"] if o["status"] == "shipped"})
    log(f"fetching {len(shipped_customers)} distinct customers for shipped orders")
    customers = {}
    for cid in shipped_customers:
        customers[cid] = call(f"/customers/{cid}", allow_404=True)
    with open(f"{OUT}/customers.json", "w") as f:
        json.dump(customers, f)

    listings = sum(len(p["items"]) for p in pages)
    log(f"done: {len(pages)} pages, {listings} listings, token fetches={token_fetches}, "
        f"customers={len(customers)} (missing={sum(1 for v in customers.values() if v is None)})")
    log(f"non-200 events: {dict(seen)}")


if __name__ == "__main__":
    main()

